const container = document.getElementById('credits-content');

// Use DocumentFragment for performance since we are adding 5000 elements
const fragment = document.createDocumentFragment();

const funnyCredits = [
    { role: "Inventor of the Skip Ad Button", name: "John" },
    { role: "First person to write 'First' on YouTube", name: "Dave" },
    { role: "Server rack #442", name: "Itself" },
    { role: "Guy who keeps restarting the router", name: "Bob" },
    { role: "Professional CAPTCHA solver", name: "Alice" },
    { role: "Chief of adding 'lol' to sentences that aren't funny", name: "Eve" },
    { role: "The person who reads Terms and Conditions", name: "Nobody" },
    { role: "Lead architect of the 'Forgot Password' loop", name: "Satan" },
    { role: "Inventor of the loading spinner", name: "Tim" },
    { role: "Accidental replier all", name: "Michael" }
];

// Insert them randomly near the beginning
funnyCredits.forEach(fc => {
    allCredits.splice(Math.floor(Math.random() * 50), 0, fc);
});

allCredits.forEach(credit => {
    const block = document.createElement('div');
    block.className = 'credit-block';

    const roleDiv = document.createElement('div');
    roleDiv.className = 'credit-role';
    roleDiv.textContent = credit.role;

    const nameDiv = document.createElement('div');
    nameDiv.className = 'credit-name';
    nameDiv.textContent = credit.name;

    block.appendChild(roleDiv);
    block.appendChild(nameDiv);

    fragment.appendChild(block);
});

container.appendChild(fragment);

// Auto scroll logic
const creditsContainer = document.querySelector('.credits-container');
let scrollSpeed = 2; // slightly faster since there are 5000
let autoScrollEnabled = true;

function autoScroll() {
    if (autoScrollEnabled) {
        creditsContainer.scrollTop += scrollSpeed;
    }
    
    if (creditsContainer.scrollTop < creditsContainer.scrollHeight - creditsContainer.clientHeight) {
        requestAnimationFrame(autoScroll);
    }
}

// Start auto scrolling after a short delay
setTimeout(() => {
    requestAnimationFrame(autoScroll);
}, 2000);

// Pause auto-scroll when user interacts
creditsContainer.addEventListener('mousedown', () => autoScrollEnabled = false);
creditsContainer.addEventListener('wheel', () => autoScrollEnabled = false);
creditsContainer.addEventListener('touchstart', () => autoScrollEnabled = false);

// Resume auto-scroll when user stops interacting
let resumeTimeout;
function resetScroll() {
    clearTimeout(resumeTimeout);
    resumeTimeout = setTimeout(() => {
        autoScrollEnabled = true;
    }, 2000); // Resume after 2 seconds of inactivity
}

creditsContainer.addEventListener('mouseup', resetScroll);
creditsContainer.addEventListener('wheel', resetScroll);
creditsContainer.addEventListener('touchend', resetScroll);

// Achievement / Troll system
const achievementContainer = document.getElementById('achievement-container');
const milestones = [
    { percent: 0.05, desc: "Still scrolling? Why?", shown: false },
    { percent: 0.15, desc: "Nothing happens at the end.", shown: false },
    { percent: 0.30, desc: "Bro is Unemployed", shown: false },
    { percent: 0.50, desc: "Go touch grass.", shown: false },
    { percent: 0.70, desc: "Do you have a life?", shown: false },
    { percent: 0.85, desc: "Almost there, jobless champion.", shown: false },
    { percent: 0.98, desc: "Unemployed Final Boss", shown: false }
];

function showAchievement(text) {
    const toast = document.createElement('div');
    toast.className = 'achievement-toast';
    
    const title = document.createElement('div');
    title.className = 'achievement-title';
    title.textContent = "Achievement Unlocked";
    
    const desc = document.createElement('div');
    desc.className = 'achievement-desc';
    desc.textContent = text;
    
    toast.appendChild(title);
    toast.appendChild(desc);
    achievementContainer.appendChild(toast);
    
    // Trigger animation
    setTimeout(() => {
        toast.classList.add('show');
    }, 10);
    
    // Remove after 5 seconds
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => {
            if (toast.parentNode) {
                toast.parentNode.removeChild(toast);
            }
        }, 500);
    }, 5000);
}

let trollTriggered = false;
let completions = parseInt(localStorage.getItem('internetCreditsCompletions')) || 0;
const trollGuy = document.getElementById('troll-guy');
const trollSpeech = document.getElementById('troll-speech');

